const body = $input.first().json.body || $input.first().json;
if (!body || !body.record) { return []; }

const record = body.record;
const oldRecord = body.old_record || null;
const oldStatus = oldRecord ? oldRecord.status : null;
const newStatus = record.status;
const bookingId = record.id;
const proof = record.payment_proof_url;

if (newStatus === 'pending' && oldStatus !== 'pending') {
  return [{ json: { booking_id: bookingId, payment_proof_url: proof, kind: 'nueva_pendiente', new_status: newStatus } }];
}

if (oldStatus === 'pending' && (newStatus === 'confirmed' || newStatus === 'cancelled')) {
  return [{ json: { booking_id: bookingId, payment_proof_url: proof, kind: 'resuelta', new_status: newStatus } }];
}

return [];

const clasif = $('Clasificar Evento de Reserva').first().json;
const kind = clasif.kind;
const newStatus = clasif.new_status || null;
const currentBookingId = String(clasif.booking_id);

let info = $input.first().json;
if (Array.isArray(info)) info = info[0];
if (!info || Object.keys(info).length === 0) return [];

// ------------------------------------------------------------
// URL DINÁMICA DE TU DOMINIO (SIN ref#)
// ------------------------------------------------------------
const DOMAIN = 'https://canchas-mino.vercel.app'; 
const secureOwnerLink = `${DOMAIN}/dashboard/bookings`;

const OWNER_FIXED_PHONE = '573006577286';
const instance = info.whatsapp_instance_name;

function normalizeCoPhone(phone) {
  if (!phone) return null;
  const digits = String(phone).replace(/\D/g, '');
  if (digits.length === 10) return '57' + digits;
  if (digits.length >= 11) return digits;
  return null;
}

function mediaTypeFromUrl(url) {
  if (!url) return null;
  const clean = String(url).split('?')[0].toLowerCase();
  if (clean.endsWith('.pdf')) return 'document';
  return 'image';
}

// ---------- Agrupar horas ----------
// Intentar usar sibling_bookings si existe, sino usamos la info actual
let siblings = Array.isArray(info.sibling_bookings) && info.sibling_bookings.length
  ? info.sibling_bookings.slice()
  : [{ pitch_name: info.pitch_name, start_time: info.start_time, booking_id: info.booking_id || currentBookingId }];

siblings = siblings.filter(sb => sb && sb.start_time);
if (siblings.length === 0) return [];

// Ordenar por hora y tomar el primero como líder
siblings.sort((a, b) => new Date(a.start_time).getTime() - new Date(b.start_time).getTime());
const leaderId = String(siblings[0].booking_id);

// Regla estricta de agrupación: solo la reserva "líder" dispara el webhook para no mandar múltiples
if (currentBookingId !== leaderId) {
  return []; 
}

const horasList = siblings.map(sb => {
  return new Date(sb.start_time).toLocaleString('es-CO', {
    timeZone: 'America/Bogota', hour: '2-digit', minute: '2-digit', hour12: true
  }) + (sb.pitch_name !== info.pitch_name ? ` (${sb.pitch_name})` : '');
});

const pitchNames = [...new Set(siblings.map(sb => sb.pitch_name).filter(Boolean))].join(' + ') || info.pitch_name || 'Cancha';
const fechaStr = new Date(siblings[0].start_time).toLocaleString('es-CO', {
  timeZone: 'America/Bogota', weekday: 'long', day: '2-digit', month: 'long', year: 'numeric'
});
const horariosStr = horasList.join(', ');
const cantidadHoras = siblings.length;
const horasLabel = cantidadHoras === 1 ? '1 hora' : `${cantidadHoras} horas`;
const shortId = info.short_id || String(leaderId).slice(0, 6);

const customerPhone = normalizeCoPhone(info.customer_phone);
const ownerPhone = normalizeCoPhone(info.owner_phone) || OWNER_FIXED_PHONE;
const sends = [];

// ============================================================
// CASO 1: reserva nueva pendiente
// ============================================================
if (kind === 'nueva_pendiente') {
  // CLIENTE: Mensaje EXACTO que pediste
  if (customerPhone) {
    sends.push({
      whatsapp_instance_name: instance,
      number: customerPhone,
      media: null,
      mediatype: null,
      text: `✅ *¡Recibimos tu comprobante!*

🏟️ ${info.company_name}
⚽ ${pitchNames}
📅 ${fechaStr}
⏰ ${horariosStr}
🎫 Ref: *#${shortId}*

Tu reserva quedó en revisión. Te avisamos apenas el dueño la confirme 🙌`,
      destino: 'cliente'
    });
  }

  // DUEÑO: Mensaje y comprobante, link al dashboard limpio (requiere logueo)
  const textoDueno = `🔔 *Nueva reserva en revisión*

🏟️ *${info.company_name}*
⚽ Cancha(s): ${pitchNames}
👤 Cliente: ${info.customer_name}
📅 ${fechaStr}
⏰ ${horariosStr}

✏️ Revisa esta reserva entrando aquí:
${secureOwnerLink}`;

  const proof = info.payment_proof_url || clasif.payment_proof_url || null;
  const proofType = mediaTypeFromUrl(proof);
  const destinatariosDueno = [...new Set([ownerPhone, OWNER_FIXED_PHONE].filter(Boolean))];

  for (const num of destinatariosDueno) {
    sends.push({
      whatsapp_instance_name: instance,
      number: num,
      media: proof,
      mediatype: proofType,
      fileName: proofType === 'document' ? `comprobante.pdf` : `comprobante.jpg`,
      text: proof ? textoDueno : textoDueno + '\n\n⚠️ El cliente no adjuntó comprobante.',
      destino: 'dueno'
    });
  }
}

// ============================================================
// CASO 2: reserva confirmada (No mandamos nada si fue cancelada)
// ============================================================
if (kind === 'resuelta') {
  const aprobada = newStatus === 'confirmed';
  const ticket = null; // No existe ticket como imagen en DB
  const textoCliente = aprobada
    ? `🎉 *¡Tu reserva fue CONFIRMADA!*

🏟️ *${info.company_name}*
⚽ *${pitchNames}*
📅 ${fechaStr}
⏰ ${horariosStr}
🎫 Ref: *#${shortId}*

Presenta este mensaje al llegar. ¡Nos vemos en la cancha! ⚽🏆

🎫 Puedes ver tu ticket digital aquí:
${DOMAIN}/reservations`
    : `❌ *Tu reserva fue rechazada/cancelada*

🏟️ ${info.company_name}
⚽ ${pitchNames}
📅 ${fechaStr}
⏰ ${horariosStr}
🎫 Ref: *#${shortId}*

El pago no pudo ser validado o la cancha ya no está disponible. Contacta al complejo para más info.`;

  if (customerPhone) {
    sends.push({
      whatsapp_instance_name: instance,
      number: customerPhone,
      media: ticket, // Pasamos el ticket aquí
      mediatype: ticket ? 'image' : null,
      fileName: ticket ? `ticket-${shortId}.jpg` : null,
      text: textoCliente,
      destino: 'cliente'
    });
  }
}

if (sends.length === 0) return [];
return sends.map(s => ({ json: s }));
